export interface QuotePayload {
  blockId?: string;
  sectionId?: string;
  label: string;
  tex: string;
}

export interface ChatStep {
  kind: "search" | "read" | "note";
  q?: string;
  target?: string;
  note?: string;
  state: "running" | "done" | "error";
  res?: string[];
  more?: number;
}

export interface DegradedInfo {
  active: boolean;
  restoresAt?: number | null;
}

export interface BlockInfo {
  code:
    | "auth_required"
    | "tier_quota_exceeded"
    | "guest_budget_exceeded"
    | "global_budget_exceeded"
    | "rate_limited"
    | "concurrent_run"
    | "oauth_unavailable"
    | "service_unavailable";
  nextAvailableAt?: number | null;
  retryAfterSec?: number | null;
}

export interface SessionJwtPayload {
  typ: "session";
  sid: string;
  tgId: number;
  tgName: string;
  browserId: string;
  iat: number;
  exp: number;
}

export interface AllowanceJwtPayload {
  typ: "allowance";
  browserId: string;
  sid?: string;
  tgId?: number;
  tgName?: string;
  tier: Tier;
  ip: string;
  fp: string;
  iat: number;
  exp: number;
}

// =============================================================================
// Codex Responses API types
// =============================================================================

export interface CodexFunctionTool {
  type: "function";
  name: string;
  description: string;
  parameters: Record<string, unknown>;
}

export type CodexInputItem =
  | {
      type: "message";
      role: "user" | "assistant";
      content: Array<{ type: "input_text" | "output_text"; text: string }>;
    }
  | {
      type: "reasoning";
      id?: string;
      summary?: unknown;
      encrypted_content?: string;
      [key: string]: unknown;
    }
  | {
      type: "function_call";
      id?: string;
      call_id: string;
      name: string;
      arguments: string;
    }
  | {
      type: "function_call_output";
      call_id: string;
      output: string;
    };

export interface RoundTokenUsage {
  inputTokens: number;
  cachedTokens: number;
  cacheWriteTokens: number;
  outputTokens: number;
}

export interface LlmRoundRequest {
  model: ModelId;
  instructions: string;
  input: CodexInputItem[];
  tools: CodexFunctionTool[];
  maxResponseChars: number;
  signal: AbortSignal;
  onDelta: (delta: string) => void;
}

export interface LlmRoundResult {
  completed: boolean;
  status: string;
  text: string;
  truncated: boolean;
  outputItems: CodexInputItem[];
  functionCalls: Array<{
    id?: string;
    callId: string;
    name: string;
    arguments: string;
  }>;
  usage: RoundTokenUsage | null;
}

export interface LlmProvider {
  runRound(req: LlmRoundRequest): Promise<LlmRoundResult>;
}

// =============================================================================
// WebSocket protocol (/v1/messages)
// =============================================================================

export type ClientWsFrame =
  | {
      type: "send";
      allowanceToken: string;
      browserToken: string;
      sessionToken?: string;
      clientRequestId: string;
      threadId?: string | null;
      retryAssistantMessageId?: string | null;
      course: string;
      docId: string;
      text: string;
      quote?: QuotePayload | null;
    }
  | {
      type: "stop";
    };

export type ServerWsFrame =
  | {
      type: "meta";
      threadId: string;
      threadTitle: string;
      userMessageId: string;
      assistantMessageId: string;
      runId: string;
      tier: Tier;
      model: ModelId;
      degraded: DegradedInfo;
    }
  | {
      type: "step";
      steps: ChatStep[];
    }
  | {
      type: "delta";
      text: string;
    }
  | {
      type: "done";
      runId: string;
      status: RunStatus;
      text: string;
      steps: ChatStep[];
      degraded: DegradedInfo;
      block: BlockInfo | null;
    }
  | {
      type: "error";
      code: string;
      message: string;
      block?: BlockInfo | null;
      retryAfterSec?: number;
    };
